import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n, limit = data[0], data[1]
    cats = data[2:2 + n]
    adjacency = [[] for _ in range(n)]

    for index in range(2 + n, len(data), 2):
        first = data[index] - 1
        second = data[index + 1] - 1
        adjacency[first].append(second)
        adjacency[second].append(first)

    stack = [(0, -1, cats[0])]
    answer = 0

    while stack:
        vertex, parent, consecutive = stack.pop()
        if consecutive > limit:
            continue

        if vertex != 0 and len(adjacency[vertex]) == 1:
            answer += 1
            continue

        for neighbor in adjacency[vertex]:
            if neighbor != parent:
                next_consecutive = consecutive + 1 if cats[neighbor] else 0
                stack.append((neighbor, vertex, next_consecutive))

    print(answer)


if __name__ == "__main__":
    main()
